    "3ffeacd7": {"text":"Sie werden es satt haben.","hash":"h1-fbd91fbf"},
    "401e5475": {"text":"Behalte deine Geschenke","hash":"h1-dd32ca10"},
    "40324377": {"text":"Bezahlen und passieren. ({money:2})","hash":"h1-d97811cc"},
