    "a412ea85": {"forms":{"select":"value","param":"self","cases":{"yes":"🎓 Sie wachsen {trait}, wie Ihr Tutor.","other":"🎓 {name} wächst {trait}, wie ihr Tutor."}},"hash":"h1-c250c3a0"},
