    "ac37e85a": {"text":"{count} Bogenschütze","hash":"h1-f83ea8fc"},
    "ac3f4693": {"forms":{"select":"value","param":"apprentice","cases":{"yes":"🧑‍🏫 {name} beginnt eine Ausbildung in {career}.","no":"🧰 {name} nimmt die Arbeit in {career} auf.","other":"🧰 {name} beginnt mit der Arbeit in {career}."}},"hash":"h1-3916f2d6"},
    "ac4b25ce": {"text":"Mit einem Rivalen einen öffentlichen Frieden geschworen.","hash":"h1-b9bcb1e6"},
