    "b71ec27f": {"text":"Lugo","hash":"h1-a859fb34"},
    "b723320a": {"text":"Imamat von Oman","hash":"h1-03b1993b"},
    "b72ba82e": {"text":"🗺 {mode} – Ihr bester Anspruch: {name}, {held} ({need} erforderlich)","hash":"h1-81630b36"},
